  class EventBus{
    constructor(){this.listeners=new Map()}
    on(name,handler){if(!this.listeners.has(name))this.listeners.set(name,new Set());this.listeners.get(name).add(handler);return()=>this.listeners.get(name)?.delete(handler)}
    emit(name,payload){for(const handler of this.listeners.get(name)||[]){try{handler(payload)}catch(error){console.error(error)}}}
  }
  class State{
    constructor(initial={}){this.value={...initial};this.bus=new EventBus()}
    get(key){return key?this.value[key]:this.value}
    set(patch){this.value={...this.value,...patch};this.bus.emit('change',this.value)}
    subscribe(handler){return this.bus.on('change',handler)}
  }
  class PerformanceMonitor{
    constructor(){this.entries=[]}
    async measure(name,operation){const start=performance.now();try{return await operation()}finally{this.entries.push({name,durationMs:Number((performance.now()-start).toFixed(2)),at:CoreUtil.nowISO()});this.entries=this.entries.slice(-100)}}
    latest(name){return[...this.entries].reverse().find(entry=>entry.name===name)||null}
    summary(){return this.entries.reduce((result,entry)=>{const values=result[entry.name]||(result[entry.name]=[]);values.push(entry.durationMs);return result},{})}
  }
