    static possibleInstants({date,time,timeZoneId}){TimeZoneEngine.validateTimeZone(timeZoneId);const guess=this.localEpochGuess(date,time),matches=[];for(const offset of this.candidateOffsets(guess,timeZoneId)){const epochMilliseconds=guess-offset*60000,p=TimeZoneEngine.parts(epochMilliseconds,timeZoneId);if(p.date===date&&p.time===time)matches.push({epochMilliseconds,utcOffsetMinutes:offset})}return[...new Map(matches.sort((a,b)=>a.epochMilliseconds-b.epochMilliseconds).map(item=>[item.epochMilliseconds,item])).values()]}
    static nearestValid({date,time,timeZoneId,direction}){const base=CoreUtil.epochMinute(date,time);for(let i=1;i<=180;i++){const minute=base+(direction<0?-i:i),candidateDate=CoreUtil.dateFromIndex(Math.floor(minute/1440)),candidateTime=CoreUtil.time(minute);if(this.possibleInstants({date:candidateDate,time:candidateTime,timeZoneId}).length)return{date:candidateDate,time:candidateTime}}return null}
