    static template(record){const value=this.common(record);value.name=String(value.name||'').trim();if(!value.name)throw CoreUtil.error('TEMPLATE-NAME-001','Template name is required.');value.dayType=this.enums.dayType.includes(value.dayType)?value.dayType:'Custom';value.sleepPolicy=this.enums.sleepPolicy.includes(value.sleepPolicy)?value.sleepPolicy:'automatic';if(value.sleepPolicy==='custom'){if(CoreUtil.clock(value.sleepBedtime)===null||CoreUtil.clock(value.sleepWakeTime)===null||value.sleepBedtime===value.sleepWakeTime)throw CoreUtil.error('SLEEP-SETTING-001','Custom bedtime and wake time must be different valid times.')}value.projectBudgetMinutes=this.nonNegative(value.projectBudgetMinutes||0,'Project budget');value.items=CoreUtil.array(value.items).map(item=>{const copy={...item,id:item.id||CoreUtil.uid(),title:String(item.title||'').trim(),kind:item.kind||'Routine',startTime:item.startTime,endTime:item.endTime,locked:item.locked!==false};if(!copy.title||CoreUtil.clock(copy.startTime)===null||CoreUtil.clock(copy.endTime)===null||copy.startTime===copy.endTime)throw CoreUtil.error('TEMPLATE-ITEM-002','Each template item needs a title and valid start/end times.');return copy});return value}
