    async move(direction){const history=await this.state();if(history.schemaVersion!==DB_SCHEMA_VERSION)throw CoreUtil.error('UNDO-SCHEMA-001','Undo history is unavailable after a schema migration.');const source=direction==='undo'?[...CoreUtil.array(history.undoStack)]:[...CoreUtil.array(history.redoStack)],target=direction==='undo'?[...CoreUtil.array(history.redoStack)]:[...CoreUtil.array(history.undoStack)],operation=source.pop();if(!operation)return null;const stores=[...new Set(operation.changes.map(change=>change.store))];await this.repo.transaction([...stores,'systemMeta','activityLog'],async tx=>{for(const change of operation.changes){const value=direction==='undo'?change.before:change.after;if(value===null||value===undefined)await tx.delete(change.store,change.id);else await tx.put(change.store,value)}target.push(operation);await tx.put('systemMeta',{...history,undoStack:direction==='undo'?source:target.slice(-this.max),redoStack:direction==='undo'?target.slice(-this.max):source,schemaVersion:DB_SCHEMA_VERSION,updatedAt:CoreUtil.nowISO()});await tx.put('activityLog',{id:CoreUtil.uid(),type:direction,text:`${direction==='undo'?'Undid':'Redid'}: ${operation.label}`,at:CoreUtil.nowISO(),createdAt:CoreUtil.nowISO(),updatedAt:CoreUtil.nowISO()})});return operation}
