    async list(){return(await this.repo.all('snapshots',{fresh:true})).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))}
    async restore(id,{createSafety=true}={}){const snapshot=typeof id==='string'?await this.repo.get('snapshots',id):id;if(!snapshot)throw CoreUtil.error('SNAPSHOT-MISSING-003','Snapshot was not found.');const payload=this.validate(snapshot);if(createSafety)await this.create('Before snapshot restore','pre-restore',{protected:true});const stores=Object.keys(payload.stores).filter(store=>STORE_NAMES.includes(store)&&store!=='snapshots');await this.repo.transaction(stores,async tx=>{for(const store of stores){const runtimeLock=store==='systemMeta'?await tx.get('systemMeta','runtime-lock:data-critical'):null;await tx.clear(store);for(const record of payload.stores[store])if(!(store==='systemMeta'&&record.id==='runtime-lock:data-critical'))await tx.put(store,record);if(runtimeLock)await tx.put('systemMeta',runtimeLock)}});await this.repo.log('snapshot-restore',`Restored snapshot: ${snapshot.name}`);return snapshot}
    async remove(id){const snapshot=await this.repo.get('snapshots',id);if(snapshot?.protected)throw CoreUtil.error('SNAPSHOT-PROTECTED-004','This safety snapshot is protected.');await this.repo.remove('snapshots',id)}
    async export(id){const snapshot=await this.repo.get('snapshots',id);if(!snapshot)throw CoreUtil.error('SNAPSHOT-MISSING-005','Snapshot was not found.');CoreUtil.download(`lifeos-snapshot-${snapshot.createdAt.slice(0,10)}.json`,JSON.stringify(snapshot,null,2),'application/json')}
    async prune(){const items=await this.list(),limits={automatic:7,weekly:4,manual:5},remove=[];for(const [kind,limit] of Object.entries(limits))remove.push(...items.filter(item=>item.kind===kind&&!item.protected).slice(limit));if(remove.length)await this.repo.transaction(['snapshots'],async tx=>{for(const item of remove)await tx.delete('snapshots',item.id)})}
    async ensureDailySnapshot(date=CoreUtil.localDate()){const settings=await this.repo.settings();if(!settings.autoSnapshots)return null;const items=await this.list();if(items.some(item=>item.kind==='automatic'&&(item.snapshotDate===date||!item.snapshotDate&&item.createdAt.startsWith(date))))return null;return this.create(`Daily — ${date}`,'automatic',{snapshotDate:date})}
    async ensureWeeklySnapshot(date=CoreUtil.localDate()){const settings=await this.repo.settings();if(!settings.autoSnapshots)return null;const weekId=CoreUtil.isoWeekId(date),items=await this.list();if(items.some(item=>item.kind==='weekly'&&item.weekId===weekId))return null;return this.create(`Weekly — ${weekId}`,'weekly',{weekId})}
