    async run(){const values=await Promise.all(STORE_NAMES.filter(name=>!['snapshots','diagnosticLog'].includes(name)).map(name=>this.repo.all(name,{fresh:true}))),names=STORE_NAMES.filter(name=>!['snapshots','diagnosticLog'].includes(name)),report=IntegrityEngine.checkData(Object.fromEntries(names.map((name,index)=>[name,values[index]])));await this.repo.save('systemMeta',{id:'integrity',...report,lastIntegrityCheck:report.checkedAt},{validate:false});return report}
