  class PWAController{
    constructor(app){this.app=app;this.registration=null}
    async register(){if(!('serviceWorker'in navigator)||!/^https?:$/.test(location.protocol))return{available:false,reason:'Standalone file mode'};try{this.registration=await navigator.serviceWorker.register('./service-worker.js');const announce=()=>this.app.notifications.notify('INFO','Application update available','Your local data will remain unchanged.',{persist:true,action:'apply-update'});if(this.registration.waiting&&navigator.serviceWorker.controller)await announce();this.registration.addEventListener('updatefound',()=>{const worker=this.registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)announce()})});navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload());return{available:true}}catch(error){await this.app.logger.record('WARN','PWAController','PWA-REGISTER-001',error.message);return{available:false,reason:error.message}}}
    async apply(){if(!this.registration?.waiting)return false;await this.app.snapshots.create('Before application update','pre-update',{protected:true});this.registration.waiting.postMessage({type:'SKIP_WAITING'});return true}
  }

