    async saveBlock(values){const old=await this.repo.get('timeBlocks',values.id),task=values.taskId?await this.repo.get('tasks',values.taskId):null,data=await this.data(),settings=await this.repo.settings();if(FreezeManager.blockFrozen(old,settings)&&!values.freezeOverride)throw CoreUtil.error('FREEZE-MANUAL-003','This period is frozen. Select “Edit anyway” to make an explicit manual override.');const candidate=TimeInterval.fromParts({sourceType:'timeBlock',sourceId:values.id,startDate:values.date,startTime:values.startTime,duration:values.duration,locked:values.locked,category:'task',projectId:task?.projectId}),conflicts=ConflictEngine.checkInterval(candidate,data,settings,{task,ignoreIds:[values.id]});if(conflicts.some(item=>item.type!=='soft'))throw CoreUtil.error(conflicts[0].code,conflicts[0].message,{conflicts});const after=this.repo.stamp('timeBlocks',{...old,...values,endTime:CoreUtil.time(CoreUtil.clock(values.startTime)+values.duration),manuallyPlaced:true,sourceType:'user',sourceId:values.id},old);delete after.freezeOverride;await this.undo.execute(`Moved or resized “${old.title}”`,[{store:'timeBlocks',id:old.id,before:old,after}],{activityType:'block-edit'})}
