    async recoverFocus(){const active=await this.focus.load();if(!active)return;this.modal.open('Active Focus session detected',`<p><b>${CoreUtil.escape(active.title)}</b></p><p>Started ${CoreUtil.formatDateTime(active.startedAt)}. Reloading did not lose the session.</p>`,`<button class="btn danger" id="discardFocus">Discard</button><button class="btn" id="finishFocus">Finish</button><button class="btn primary" id="resumeFocus">Resume</button>`);document.getElementById('resumeFocus').onclick=()=>{this.modal.close();this.focus.show()};document.getElementById('finishFocus').onclick=()=>{this.modal.close();this.focus.finish('Recovered',false)};document.getElementById('discardFocus').onclick=()=>{this.modal.close();this.focus.discard()}}

    async openFreezeDialog(){const settings=await this.repo.settings(),freeze=FreezeManager.active(settings);this.modal.open('Freeze Horizon',`${freeze?`<div class="note"><b>${CoreUtil.escape(FreezeManager.describe(freeze))}</b><div>Automatic planning and repair preserve this period; manual editing can override explicitly.</div></div>`:'<p class="muted">Temporarily protect the near-term plan from automatic movement.</p>'}<div class="grid grid-2 flow-gap-12"><button class="btn" data-action="set-freeze" data-freeze="2h">Freeze next 2 hours</button><button class="btn" data-action="set-freeze" data-freeze="4h">Freeze next 4 hours</button><button class="btn" data-action="set-freeze" data-freeze="today">Freeze rest of today</button><button class="btn" data-action="set-freeze" data-freeze="tomorrow">Freeze until tomorrow morning</button></div><form data-form="freeze-custom" class="flow-gap-14"><h3>Custom freeze</h3><div class="form-grid"><div class="field"><label>Start date</label><input type="date" name="startDate" value="${CoreUtil.localDate()}" required></div><div class="field"><label>Start time</label><input type="time" name="startTime" value="${CoreUtil.time(new Date().getHours()*60+new Date().getMinutes())}" required></div><div class="field"><label>End date</label><input type="date" name="endDate" value="${CoreUtil.localDate()}" required></div><div class="field"><label>End time</label><input type="time" name="endTime" value="23:59" required></div></div><button class="btn primary">Apply custom freeze</button></form>`,`<button class="btn" data-action="close-dialog">Close</button>${freeze?'<button class="btn danger" data-action="clear-freeze">Clear freeze</button>':''}`,{subtitle:'Freeze is temporary protection, not a permanent lock.'})}
    async setFreeze(kind){const freeze=FreezeManager.createPreset(kind);await this.repo.setting('planningFreeze',freeze);await this.repo.log('freeze-applied',`Applied ${kind} plan freeze`,{startMinute:freeze.startMinute,endMinute:freeze.endMinute});await this.notifications.notify('SUCCESS','Plan freeze applied',FreezeManager.describe(freeze));this.modal.close();await this.render()}
    async setCustomFreeze(values){const start=CoreUtil.epochMinute(values.startDate,values.startTime),end=CoreUtil.epochMinute(values.endDate,values.endTime);if(end<=start)throw CoreUtil.error('FREEZE-CUSTOM-002','Freeze end must be after its start.');const freeze={startMinute:start,endMinute:end,createdAt:CoreUtil.nowISO(),createdBy:'user',label:'custom'};await this.repo.setting('planningFreeze',freeze);await this.repo.log('freeze-applied','Applied custom plan freeze',{startMinute:freeze.startMinute,endMinute:freeze.endMinute});await this.notifications.notify('SUCCESS','Custom plan freeze applied',FreezeManager.describe(freeze))}
