    async previewWeek(){const [data,settings]=await Promise.all([this.data(),this.repo.settings()]),model=PersonalPlanningModel.build(data),weekStart=CoreUtil.startOfWeek(CoreUtil.localDate()),plan=await this.performance.measure('week-scheduler',async()=>new WeekScheduler(data,settings,model).generate(weekStart));if(!plan.planned.length){this.modal.open('Generate Week',`<div class="warning"><b>No additional work fits safely.</b><div>Check task dependencies, project daily/weekly limits, Day Template budgets and physical capacity.</div></div>${plan.projectReports.filter(row=>row.shortfall).map(row=>`<div class="item"><div class="item-main"><b>${CoreUtil.escape(row.project.title)}</b><div class="muted">Shortfall ${CoreUtil.duration(row.shortfall)} · ${CoreUtil.escape(row.causes.join(' · '))}</div></div></div>`).join('')}`,'<button class="btn primary" data-action="close-dialog">Close</button>');return}this.state.set({pending:{type:'week',plan}});const days=plan.dayReports.filter(day=>day.created).map(day=>`<div class="item"><div class="item-main"><b>${CoreUtil.formatDate(day.date)} · ${day.created} blocks</b><div class="muted">${CoreUtil.duration(day.minutes)} focused work · ${day.capacity.type.label} Day</div></div></div>`).join(''),shortfalls=plan.projectReports.filter(row=>row.shortfall);this.modal.open('Generate Week preview',`${this.schedulePreviewHTML(plan)}<h3 class="flow-gap-15">Daily allocation</h3><div class="list">${days}</div>${shortfalls.length?`<div class="warning flow-gap-12"><b>Demand that does not fit</b>${shortfalls.map(row=>`<div>${CoreUtil.escape(row.project.title)}: ${CoreUtil.duration(row.shortfall)} · ${CoreUtil.escape(row.causes.join(' · ')||'insufficient eligible capacity')}</div>`).join('')}</div>`:''}`,`<button class="btn" data-action="close-dialog">Cancel</button><button class="btn primary" data-action="apply-week-plan">Commit week</button>`,{subtitle:'Preview step 8 of the weekly planning workflow.'})}
